- All 3 samples survive a restart in that window, and another restart after OOO compaction.
- After OOO compaction, the next checkpoint drops `ref2` (retention is bounded) and keeps `ref1`.

```go
// TestWALCheckpointKeepsSeriesRecordsUsedByWBL checks that a WAL checkpoint keeps the series record of a
// reference that WAL replay merged into another series while the WBL still uses it, and drops the record
// once out-of-order compaction has truncated the WBL.
func TestWALCheckpointKeepsSeriesRecordsUsedByWBL(t *testing.T) {
	const blockRange = 1000
	opts := DefaultOptions()
	opts.MinBlockDuration = blockRange
	opts.MaxBlockDuration = blockRange
	opts.OutOfOrderTimeWindow = 10 * blockRange

	db := newTestDB(t, withOpts(opts))
	db.DisableCompactions()
	dir := db.Dir()

	lbls := labels.FromStrings("foo", "bar")
	other := labels.FromStrings("foo", "other")
	appendSample := func(l labels.Labels, ts int64) storage.SeriesRef {
		app := db.Appender(context.Background())
		ref, err := app.Append(0, l, ts, float64(ts))
		require.NoError(t, err)
		require.NoError(t, app.Commit())
		return ref
	}
	reopen := func() {
		require.NoError(t, db.Close())
		db = newTestDB(t, withOpts(opts), withDir(dir))
		db.DisableCompactions()
	}
	// nextWALSegments starts enough WAL segments for the next WAL truncation to checkpoint all previous segments.
	nextWALSegments := func() {
		for range 3 {
			_, err := db.head.wal.NextSegment()
			require.NoError(t, err)
		}
	}
	// checkpointRefs returns the series references in the last WAL checkpoint.
	checkpointRefs := func() map[chunks.HeadSeriesRef]struct{} {
		cp, _, err := wlog.LastCheckpoint(db.head.wal.Dir())
		require.NoError(t, err)
		refs := map[chunks.HeadSeriesRef]struct{}{}
		for _, rec := range readTestWAL(t, cp) {
			if series, ok := rec.([]record.RefSeries); ok {
				for _, s := range series {
					refs[s.Ref] = struct{}{}
				}
			}
		}
		return refs
	}
	verifySamples := func() {
		q, err := db.Querier(0, 4*blockRange)
		require.NoError(t, err)
		require.Equal(t, map[string][]chunks.Sample{lbls.String(): {
			sample{t: 100, f: 100},
			sample{t: 1500, f: 1500},
			sample{t: 1700, f: 1700},
		}}, query(t, q, labels.MustNewMatcher(labels.MatchEqual, "foo", "bar")))
	}

	ref1 := appendSample(lbls, 100)
	appendSample(other, 1600)
	// Head compaction writes the series into a block and drops it from the head.
	require.NoError(t, db.CompactHead(NewRangeHead(db.head, 0, blockRange-1)))
	require.Nil(t, db.head.series.getByID(chunks.HeadSeriesRef(ref1)))

	// The series comes back under a new reference, and the WBL logs an out-of-order sample under it.
	ref2 := appendSample(lbls, 1700)
	require.NotEqual(t, ref1, ref2)
	appendSample(lbls, 1500)

	// WAL replay merges both references into one series.
	reopen()

	// In-order head compaction checkpoints the WAL past the in-order samples of ref2.
	appendSample(other, 3200)
	nextWALSegments()
	require.NoError(t, db.CompactHead(NewRangeHead(db.head, blockRange, 2*blockRange-1)))
	require.Contains(t, checkpointRefs(), chunks.HeadSeriesRef(ref2))

	// Restart before out-of-order compaction.
	reopen()
	verifySamples()

	// Out-of-order compaction truncates the WBL, so the series record of ref2 is no longer needed.
	require.NoError(t, db.CompactOOOHead(context.Background()))
	nextWALSegments()
	require.NoError(t, db.head.truncateWAL(2*blockRange+1))
	refs := checkpointRefs()
	require.Contains(t, refs, chunks.HeadSeriesRef(ref1))
	require.NotContains(t, refs, chunks.HeadSeriesRef(ref2))

	reopen()
	verifySamples()
}
```

